+                    <button class="btn-next" @onclick="NextStep">Next</button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 3: References -->
+        @if (_currentStep == 2)
+        {
+            <div class="form-step">
+                <h2>References</h2>
+                @for (int i = 0; i < _references.Count; i++)
+                {
+                    var index = i;
+                    <div class="reference-card">
+                        <div class="work-entry-header">
+                            <h3>Reference @(index + 1)</h3>
+                            @if (_references.Count > 2)
+                            {
+                                <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
+                            }
+                        </div>
+                        <div class="form-group">
+                            <label>Name *</label>
+                            <input type="text" @bind="_references[index].Name" placeholder="Reference name" />
+                        </div>
+                        <div class="form-group">
+                            <label>Relationship *</label>
+                            <input type="text" @bind="_references[index].Relationship" placeholder="e.g., Former Manager" />
+                        </div>
+                        <div class="form-group">
+                            <label>Email *</label>
+                            <input type="email" @bind="_references[index].Email" placeholder="Reference email" />
+                        </div>
+                        <div class="form-group">
+                            <label>Phone *</label>
+                            <input type="tel" @bind="_references[index].Phone" placeholder="Reference phone" />
+                        </div>
+                    </div>
+                }
+                @if (_references.Count < 3)
+                {
+                    <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
+                }
+                <div class="form-buttons">
+                    <button class="btn-back" @onclick="PreviousStep">Back</button>
+                    <button class="btn-next" @onclick="NextStep">Next</button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 4: Cover Letter -->
+        @if (_currentStep == 3)
+        {
+            <div class="form-step">
+                <h2>Cover Letter</h2>
+                <div class="form-group">
+                    <label for="coverLetter">Write your cover letter</label>
+                    <textarea id="coverLetter" @bind="_coverLetter" @bind:event="oninput" placeholder="Tell us why you're a great fit..." rows="12" maxlength="2000"></textarea>
+                    <div class="character-count">@_coverLetter.Length / 2000 characters</div>
+                </div>
+                <div class="form-buttons">
+                    <button class="btn-back" @onclick="PreviousStep">Back</button>
+                    <button class="btn-next" @onclick="NextStep">Next</button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 5: Review & Submit -->
+        @if (_currentStep == 4)
+        {
+            <div class="form-step">
+                <h2>Review &amp; Submit</h2>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Personal Information</h3>
+                        <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
+                    </div>
+                    <dl>
+                        <dt>Full Name</dt><dd>@_fullName</dd>
+                        <dt>Email</dt><dd>@_email</dd>
+                        <dt>Phone</dt><dd>@_phone</dd>
+                        <dt>Address</dt><dd>@_address</dd>
+                    </dl>
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Work History</h3>
+                        <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
+                    </div>
+                    @foreach (var entry in _workEntries)
+                    {
+                        <div class="review-entry">
+                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                            <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
+                            @if (!string.IsNullOrWhiteSpace(entry.Description))
+                            {
+                                <p>@entry.Description</p>
+                            }
+                        </div>
+                    }
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>References</h3>
+                        <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
+                    </div>
+                    @foreach (var reference in _references)
+                    {
+                        <div class="review-entry">
+                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
+                            <span>@reference.Email | @reference.Phone</span>
+                        </div>
+                    }
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Cover Letter</h3>
+                        <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
+                    </div>
+                    <p class="cover-letter-preview">@_coverLetter</p>
+                </div>
+
+                <div class="form-buttons">
+                    <button class="btn-back" @onclick="PreviousStep">Back</button>
+                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                        @if (_isSubmitting)
+                        {
+                            <span>Submitting...</span>
+                        }
+                        else
+                        {
+                            <span>Submit Application</span>
+                        }
+                    </button>
+                </div>
+            </div>
+        }
+    }
+    else
+    {
+        <!-- Confirmation -->
+        <div class="confirmation">
+            <div class="confirmation-icon">&#10003;</div>
+            <h2>Application Submitted!</h2>
+            <p>Thank you for your application. Your application ID is:</p>
+            <div class="application-id">#@_applicationId</div>
+            <p>We will review your application and get back to you soon.</p>
+        </div>
+    }
+</div>
+
+@code {
+    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+    private int _currentStep = 0;
+    private string _errorMessage = string.Empty;
+    private bool _isValidating;
+    private bool _isSubmitting;
+    private bool _submitted;
+    private int _applicationId;
+
+    // Step 1 fields
+    private string _fullName = string.Empty;
+    private string _email = string.Empty;
+    private string _phone = string.Empty;
+    private string _address = string.Empty;
+
+    // Step 2 fields
+    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
+
+    // Step 3 fields
+    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4 fields
+    private string _coverLetter = string.Empty;
+
+    private string GetStepClass(int stepIndex)
+    {
+        if (stepIndex == _currentStep) return "active";
+        if (stepIndex < _currentStep) return "completed";
+        return "future";
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step < _currentStep)
+        {
+            _currentStep = step;
+            _errorMessage = string.Empty;
+        }
+    }
+
+    private async Task NextStep()
+    {
+        _errorMessage = string.Empty;
+
+        if (!ValidateCurrentStep())
+            return;
+
+        if (_currentStep == 0)
+        {
+            _isValidating = true;
+            StateHasChanged();
+            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
+            _isValidating = false;
+            if (!emailValid)
+            {
+                _errorMessage = "The email address provided is not valid.";
+                return;
+            }
+        }
+
+        _currentStep++;
+    }
+
+    private void PreviousStep()
+    {
+        if (_currentStep > 0)
+        {
+            _currentStep--;
+            _errorMessage = string.Empty;
+        }
+    }
+
+    private bool ValidateCurrentStep()
+    {
+        switch (_currentStep)
+        {
+            case 0:
+                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
+                    string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
+                {
+                    _errorMessage = "Please fill in all required fields.";
+                    return false;
+                }
+                break;
+            case 1:
+                foreach (var entry in _workEntries)
+                {
+                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
+                        entry.StartDate == default)
+                    {
+                        _errorMessage = "Please fill in company name, job title, and start date for all positions.";
+                        return false;
+                    }
+                }
+                break;
+            case 2:
+                foreach (var reference in _references)
+                {
+                    if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
+                        string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
+                    {
+                        _errorMessage = "Please fill in all fields for each reference.";
+                        return false;
+                    }
+                }
+                break;
+            case 3:
+                if (string.IsNullOrWhiteSpace(_coverLetter))
+                {
+                    _errorMessage = "Please write a cover letter.";
+                    return false;
+                }
+                break;
+        }
+        return true;
+    }
+
+    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (_workEntries.Count > 1)
+            _workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (_references.Count < 3)
+            _references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (_references.Count > 2)
+            _references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+        _errorMessage = string.Empty;
+        StateHasChanged();
+
+        try
+        {
+            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+            var workHistory = new WorkHistory(_workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? string.Empty)
+            ).ToList());
+            var references = _references.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
+            ).ToList();
+            var application = new JobApplication(personal, workHistory, references, _coverLetter);
+
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _submitted = true;
+        }
+        catch (Exception)
+        {
+            _errorMessage = "An error occurred while submitting your application. Please try again.";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string? Description { get; set; }
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
+

toolArgs.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    transition: all 0.3s ease;
}

.step.active .step-circle {
    background-color: #4361ee;
    color: white;
    box-shadow: 0 0 0 4px rgba(67, 97, 238, 0.2);
}

.step.completed .step-circle {
    background-color: #2ecc71;
    color: white;
}

.step.future .step-circle {
    background-color: #e0e0e0;
    color: #999;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step-connector {
    flex: 1;
    height: 3px;
    background-color: #e0e0e0;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    min-width: 20px;
}

.step-connector.completed {
    background-color: #2ecc71;
}

/* Form Steps */
.form-step {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.form-step h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
    border-bottom: 2px solid #f0f0f0;
    padding-bottom: 0.75rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.7rem 1rem;
    border: 1.5px solid #ddd;
    border-radius: 8px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: 18px;
    height: 18px;
}

.checkbox-group label {
    display: inline;
    margin-bottom: 0;
    font-weight: normal;
}

/* Buttons */
.form-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #f0f0f0;
}

.btn-next,
.btn-submit {
    background-color: #4361ee;
    color: white;
    border: none;
    padding: 0.75rem 2rem;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.2s;
    margin-left: auto;
}

.btn-next:hover,
.btn-submit:hover {
    background-color: #3651d4;
}

.btn-next:disabled,
.btn-submit:disabled {
    background-color: #a0a0a0;
    cursor: not-allowed;
}

.btn-back {
    background-color: transparent;
    color: #666;
    border: 1.5px solid #ddd;
    padding: 0.75rem 2rem;
    border-radius: 8px;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-back:hover {
    border-color: #4361ee;
    color: #4361ee;
}

.btn-add {
    background-color: #f8f9fa;
    color: #4361ee;
    border: 1.5px dashed #4361ee;
    padding: 0.6rem 1.5rem;
    border-radius: 8px;
    font-size: 0.9rem;
    cursor: pointer;
    width: 100%;
    margin-top: 1rem;
    transition: background-color 0.2s;
}

.btn-add:hover {
    background-color: #eef0ff;
}

.btn-remove {
    background-color: transparent;
    color: #e74c3c;
    border: 1px solid #e74c3c;
    padding: 0.3rem 0.8rem;
    border-radius: 6px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-remove:hover {
    background-color: #e74c3c;
    color: white;
}

.btn-edit {
    background-color: transparent;
    color: #4361ee;
    border: none;
    padding: 0.3rem 0.8rem;
    font-size: 0.85rem;
    cursor: pointer;
    text-decoration: underline;
}

.btn-edit:hover {
    color: #3651d4;
}

/* Cards */
.work-entry-card,
.reference-card {
    background-color: #f8f9fa;
    border: 1px solid #e9ecef;
    border-radius: 10px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    color: #333;
    font-size: 1rem;
}

/* Character Count */
.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.4rem;
}

/* Error Message */
.error-message {
    background-color: #fff3f3;
    color: #e74c3c;
    border: 1px solid #ffd0d0;
    border-radius: 8px;
    padding: 0.75rem 1rem;
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
}

/* Review Section */
.review-section {
    background-color: #f8f9fa;
    border-radius: 10px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    color: #1a1a2e;
    font-size: 1.05rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
    font-size: 0.9rem;
}

.review-section dd {
    margin: 0;
    color: #333;
    font-size: 0.9rem;
}

.review-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #e9ecef;
}

.review-entry:last-child {
    border-bottom: none;
}

.review-entry p {
    margin: 0.4rem 0 0;
    color: #555;
    font-size: 0.9rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    color: #333;
    font-size: 0.9rem;
    line-height: 1.6;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: white;
    border-radius: 12px;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.confirmation-icon {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background-color: #2ecc71;
    color: white;
    font-size: 2.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.confirmation h2 {
    color: #1a1a2e;
    margin-bottom: 0.5rem;
}

.application-id {
    font-size: 1.5rem;
    font-weight: bold;
    color: #4361ee;
    margin: 1rem 0;
}

.btn-submit {
    background-color: #2ecc71;
}

.btn-submit:hover {
    background-color: #27ae60;
}

